NAMES = {'cctv1': 'CCTV-1 综合', 'cctv2': 'CCTV-2 财经', 'cctv4': 'CCTV-4 中文国际'}
API_HOSTS = {'vdnx.live.cntv.cn', 'vdnxbk.live.cntv.cn'}
API_PATH = '/api/v3/vdn/live'
MEDIA_SUFFIXES = ('cntv.cn', 'cntv.com', 'cctv.cn', 'cctv.com', 'bdydns.com',
                  'myqcloud.com', 'kcdnvip.com', 'volcfcdn.com', 'cdn20.com',
                  'myalicdn.com', 'alicdn.com', 'wscdns.com', 'ks-cdn.com',
                  'ksyungslb.com', 'myhwcdn.cn', 'chinanetcenter.com')
REQUEST_HEADERS = {'referer', 'origin', 'user-agent', 'auth-key', 'vtoken', 'accept-language'}
MAX_BODY = 32 * 1024 * 1024
LOG = logging.getLogger('cbox')


class LiveError(Exception):
    pass


class MediaCapabilityError(LiveError):
    pass


class UpstreamError(LiveError):
    def __init__(self, status, target=None):
        self.status = status
        parsed = urlparse.urlsplit(target or '')
        self.host = parsed.hostname
        self.stage = 'manifest' if parsed.path.endswith('.m3u8') else ('api' if parsed.hostname == 'bkliveinfo.ysp.cctv.cn' or parsed.path == API_PATH else 'media')
        detail = f'（{self.host}，{self.stage}）' if self.host else ''
        super().__init__(f'上游 HTTP {status}' + detail)


def is_hls(body):
    return body.removeprefix(b'\xef\xbb\xbf').lstrip().startswith(b'#EXTM3U')


def valid_media_url(value):
    try:
        u = urlparse.urlsplit(value)
        host = (u.hostname or '').lower()
        return (u.scheme in ('https', 'http') and not u.username and not u.password
                and (u.port in (None, 80, 443) or (host == 'idclive.hljtv.com' and u.port == 4430)) and not any(c in value for c in '\r\n')
                and any(host == s or host.endswith('.' + s) for s in MEDIA_SUFFIXES + ('nxhhy.cn', 'hljtv.com', 'yangshipin.cn', 'ningxiahuangheyun.com')))
    except (ValueError, TypeError):
        return False


def har_profiles(paths):
    result = {}
    for path in paths:
        root = json.loads(Path(path).read_text(encoding='utf-8-sig'))
        for e in root.get('log', {}).get('entries', []):
            request, response = e.get('request', {}), e.get('response', {})
            u = urlparse.urlsplit(request.get('url', ''))
            if urlparse.parse_qs(u.query).get('vn', [''])[0] != '3002':
                continue
            if (u.scheme != 'https' or u.hostname not in API_HOSTS or u.path != API_PATH
                    or request.get('method') != 'GET' or response.get('status') != 200):
                continue
            content = response.get('content', {})
            raw = content.get('text', '')
            if content.get('encoding') == 'base64':
                raw = base64.b64decode(raw).decode('utf-8')
            try:
                data = json.loads(raw)
                if not isinstance(data, dict):
                    continue
            except (ValueError, TypeError):
                continue
            if data.get('ack') != 'yes':
                continue
            channel = urlparse.parse_qs(u.query).get('channel', [''])[0]
            if not re.fullmatch(r'[A-Za-z0-9_-]{1,64}', channel):
                continue
            headers = {x['name'].lower(): x['value'] for x in request.get('headers', [])
                       if x['name'].lower() in REQUEST_HEADERS}
            profile = {'url': request['url'], 'headers': headers,
                       'captured_at': e.get('startedDateTime', ''), 'source': Path(path).name}
            if channel not in result or profile['captured_at'] >= result[channel]['captured_at']:
                result[channel] = profile
    return result


class CheckedRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, fp, code, message, headers, target):
        u = urlparse.urlsplit(target)
        if not valid_media_url(target) and not (u.scheme == 'https' and u.hostname in API_HOSTS and u.path == API_PATH):
            raise LiveError('上游重定向到了未支持的域名')
        return super().redirect_request(request, fp, code, message, headers, target)


class Cache:
    def __init__(self, mb):
        self.limit = max(0, mb) * 1024 * 1024
        self.size = 0
        self.entries = collections.OrderedDict()
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            entry = self.entries.get(key)
            if not entry:
                return None
            expiry, data = entry
            if expiry < time.monotonic():
                self.size -= len(data[2])
                del self.entries[key]
                return None
            self.entries.move_to_end(key)
            return data

    def put(self, key, data):
        length = len(data[2])
        if not self.limit or length > self.limit:
            return
        with self.lock:
            old = self.entries.pop(key, None)
            if old:
                self.size -= len(old[1][2])
            self.entries[key] = (time.monotonic() + 20, data)
            self.size += length
            while self.size > self.limit:
                _, (_, value) = self.entries.popitem(last=False)
                self.size -= len(value[2])


