# Additional sources adapted from akiralereal/iptv (GPL-3.0), commit
# e475b2f6d24029f844ada2b362d703c8b88c2e9b. See --licenses.

# Python adaptation of akiralereal/iptv extractors/yangshipin/ckey.js,
# commit e475b2f6d24029f844ada2b362d703c8b88c2e9b; GPL-3.0.
def _ysp_u32(value):
    return (value & 0xffffffff).to_bytes(4, 'big')


def _ysp_lp(value):
    value = value if isinstance(value, bytes) else str(value).encode('utf-8')
    return len(value).to_bytes(2, 'big') + value


def _ysp_checksum(value):
    result = 0
    for byte in value:
        result = (result * 0x83 + byte) & 0x7fffffff
    return result


def _ysp_tea_block(block, key):
    y, z = int.from_bytes(block[:4], 'big'), int.from_bytes(block[4:], 'big')
    k = [int.from_bytes(key[i:i + 4], 'big') for i in (0, 4, 8, 12)]
    total = 0
    for _ in range(16):
        total = (total + 0x9e3779b9) & 0xffffffff
        y = (y + (((z << 4) + k[0]) ^ (z + total) ^ ((z >> 5) + k[1]))) & 0xffffffff
        z = (z + (((y << 4) + k[2]) ^ (y + total) ^ ((y >> 5) + k[3]))) & 0xffffffff
    return _ysp_u32(y) + _ysp_u32(z)


def _ysp_tea_packet(data, key, random_bytes):
    padding = (8 - ((len(data) + 10) % 8)) % 8
    plain = bytes([(random_bytes(1)[0] & 0xf8) | padding]) + random_bytes(padding) + random_bytes(2) + data + bytes(7)
    previous_plain, previous_cipher, output = bytes(8), bytes(8), bytearray()
    for start in range(0, len(plain), 8):
        mixed = bytes(a ^ b for a, b in zip(plain[start:start + 8], previous_cipher))
        cipher = bytes(a ^ b for a, b in zip(_ysp_tea_block(mixed, key), previous_plain))
        output.extend(cipher)
        previous_plain, previous_cipher = mixed, cipher
    return bytes(output)


def source_ckey(channel_id, now=None, guid=None, uid=None, random_bytes=None):
    random_bytes = random_bytes or secrets.token_bytes
    timestamp = int(time.time() if now is None else now / 1000)
    guid = guid or random_bytes(16).hex()
    uid = uid or random_bytes(4).hex().upper()
    guard_body = _ysp_u32(timestamp) + _ysp_lp(guid[-5:] if len(guid) >= 5 else '') + _ysp_lp('') + _ysp_lp('') + _ysp_lp('-1')
    guard_plain = _ysp_lp(guard_body)
    guard = _ysp_tea_packet(guard_plain, bytes.fromhex('110DBEC10C23E7D2E56A1CAD6914EF1B'), random_bytes) + _ysp_u32(_ysp_checksum(guard_plain))
    guard_xor = bytes.fromhex('b3c953a06913ad4d')
    guard = bytes(v ^ guard_xor[i & 7] for i, v in enumerate(guard)).hex().upper()
    body = (bytes.fromhex('0000004200000004000004d2') + _ysp_u32(4330403) + _ysp_u32(0) + _ysp_u32(timestamp)
            + b''.join(_ysp_lp(value) for value in ('dcgh', '_zj1A5Gh6QYcxWjIUGos2w==', 'V8.22.1035.3031', str(channel_id), guid))
            + _ysp_u32(1) + _ysp_u32(1)
            + b''.join(_ysp_lp(value) for value in (uid, 'nil', '57eab0c4-2c58-44c6-8ae9-dd2757525dc5', 'nil',
                         'v0.1.000', 'com.cctv.yangshipin.app.iphone', '4330403', 'ex_json_bus', 'ex_json_vs', guard)))
    packet = bytearray(_ysp_lp(body))
    packet[18:22] = _ysp_u32(_ysp_checksum(packet))
    encrypted = _ysp_tea_packet(bytes(packet), bytes.fromhex('59b2f7cf725ef43c34fdd7c123411ed3'), random_bytes) + _ysp_u32(_ysp_checksum(packet))
    xor = bytes.fromhex('842eed08f066e6ea48b4caa991ed6ff3')
    encrypted = bytes(v ^ xor[i & 15] for i, v in enumerate(encrypted))
    key = base64.b64encode(encrypted).decode().replace('+', '_').replace('/', '-').rstrip('=')
    flow = __import__('uuid').uuid4()
    return {'cKey': '--01' + key, 'guid': guid, 'timestamp': timestamp, 'flowId': str(flow).upper() + '_4330403'}


def protobuf_fields(data):
    if len(data) > 512 * 1024:
        raise LiveError('节目单数据过大')
    pos = 0
    def varint():
        nonlocal pos
        value = 0
        for shift in range(0, 64, 7):
            if pos >= len(data):
                raise LiveError('节目单数据被截断')
            byte = data[pos]
            pos += 1
            value |= (byte & 127) << shift
            if not byte & 128:
                return value
        raise LiveError('节目单整数格式错误')
    while pos < len(data):
        tag = varint()
        field, wire = tag >> 3, tag & 7
        if not field:
            raise LiveError('节目单字段格式错误')
        if wire == 0:
            yield field, varint()
            continue
        if wire == 2:
            length = varint()
        elif wire in (1, 5):
            length = 8 if wire == 1 else 4
        else:
            raise LiveError('节目单字段类型不支持')
        if pos + length > len(data):
            raise LiveError('节目单数据被截断')
        value = data[pos:pos + length]
        pos += length
        if wire == 2:
            yield field, value


class SourceEpgStore(EpgStore):
    def _fetch_one(self, channel):
        profile = self.client.profiles[channel]
        if self.client.api_mode == 'ysp':
            today = datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).date()
            rows, errors = [], []
            for delta in (0, 1):
                if self.closed.is_set():
                    raise LiveError('EPG 更新已停止')
                day = (today + datetime.timedelta(days=delta)).strftime('%Y%m%d')
                target = 'https://capi.yangshipin.cn/api/yspepg/program/' + profile['livePid'] + '/' + day
                try:
                    _, _, body, _ = self.client.fetch(target)
                    for field, value in protobuf_fields(body):
                        if field != 2 or not isinstance(value, bytes):
                            continue
                        entry = dict(protobuf_fields(value))
                        title = entry.get(2, b'')
                        if isinstance(title, bytes):
                            rows.append({'title': title.decode('utf-8', errors='replace'),
                                         'startTime': entry.get(3), 'endTime': entry.get(4)})
                except LiveError as exc:
                    errors.append(str(exc))
            result = normalize_epg({'code': 200, 'EPG': rows}, channel)
            if not result and errors:
                raise LiveError('央视频节目单无可用数据；' + errors[-1])
            return result
        if profile['provider'] == 'ningxia':
            try:
                payload = self.client.ningxia_epg()
            except LiveError:
                if profile.get('cntv_epg'):
                    return super()._fetch_one(profile['cntv_epg'])
                raise
            rows = []
            for menu in payload.get('data', {}).get('menu', []):
                if menu.get('ename') == profile['epg_key'] and menu.get('types') == 'tvpro':
                    rows.extend({'title': r.get('name'), 'startTime': r.get('stimestamp'),
                                 'endTime': r.get('otimestamp')} for r in menu.get('playbill', []))
            return normalize_epg({'code': 200, 'EPG': rows}, channel)
        if profile.get('cntv_epg'):
            return super()._fetch_one(profile['cntv_epg'])
        raise LiveError('该新增来源暂无已接入的官方节目单')


class SourceClient(Client):
    def __init__(self, args, mode):
        copied = argparse.Namespace(**vars(args))
        copied.api_mode, copied.har, copied.channels = 'app', [], None
        super().__init__(copied, init_epg=False)
        self.args = argparse.Namespace(**vars(args))
        self.args.audio = False
        self.api_mode = mode
        self.profiles = {('ysp-' + r['id']): dict(r, provider='ysp') for r in YSP_CHANNELS} if mode == 'ysp' else dict(REGIONAL_CHANNELS)
        if args.channels:
            chosen = args.channels.split(',')
            if any(ch not in self.profiles for ch in chosen):
                raise LiveError('新增源频道 ID 不正确；查看 /' + mode + '/channels.json')
            self.profiles = {ch: self.profiles[ch] for ch in chosen}
        if 'ningxia-nxws' in self.profiles:
            self.profiles['ningxia-nxws']['cntv_epg'] = 'ningxia'
        self.metadata = {ch: {'name': p['name'], 'group': p.get('group', '央视频'), 'logo': p.get('logo', '')}
                         for ch, p in self.profiles.items()}
        self.subscription_channels = set(self.profiles)
        self.locks = {ch: threading.Lock() for ch in self.profiles}
        self.har_stamps = ()
        self.epg_cache_file = 'epg-' + mode + '-v1.json'
        self.epg = SourceEpgStore(self)
        self.epg_payload_lock = threading.Lock()
        self.epg_payload = None
        self.epg_payload_at = 0
        self.playlist_locks = {ch: threading.Lock() for ch in self.profiles}
        self.manifest_cache = {}
        self.segment_pins = {}
        self.refresh_jobs = {}
        self.refresh_errors = {}
        self.source_cooling = {}
        self.ticket_tokens = 8.0
        self.ticket_refilled_at = time.monotonic()

    def refresh_har(self, force=False):
        return

    def ningxia_epg(self):
        with self.epg_payload_lock:
            if self.epg_payload is not None and time.monotonic() - self.epg_payload_at < 600:
                return self.epg_payload
            _, _, body, _ = self.fetch('https://api.ningxiahuangheyun.com/?mod=get_appdata&appid=nxtv-tv')
            try:
                payload = json.loads(body)
                if str(payload.get('errcode')) != '200' or not isinstance(payload.get('data', {}).get('menu'), list):
                    raise ValueError()
            except (ValueError, TypeError, AttributeError):
                raise LiveError('宁夏官方节目单格式错误') from None
            self.epg_payload, self.epg_payload_at = payload, time.monotonic()
            return payload

    def media_headers(self, channel):
        return {'User-Agent': 'qqlive', 'Referer': 'https://live.cctv.cn/'} if self.api_mode == 'ysp' else {'User-Agent': 'Mozilla/5.0'}

    def should_process(self, target, kind=None):
        return False

    def resolve(self, channel, force=False):
        if channel not in self.profiles:
            raise LiveError('未知新增源频道')
        with self.locks[channel]:
            cached = self.resolved.get(channel)
            if cached and not force and time.monotonic() - cached[0] < (getattr(self.args, 'ysp_ticket_ttl', 300) if self.api_mode == 'ysp' else min(self.args.resolve_ttl, 45)):
                return cached[1]
            try:
                profile = self.profiles[channel]
                if self.api_mode == 'ysp':
                    with self.state_lock:
                        now = time.monotonic()
                        held = self.manifest_cache.get(channel)
                        active = held and now - held[0] < 30
                        if not active:
                            self.ticket_tokens = min(8.0, self.ticket_tokens + max(0, now - self.ticket_refilled_at) * 8 / 60)
                            self.ticket_refilled_at = now
                            if self.ticket_tokens < 1:
                                raise LiveError('央视频新频道取票过快；请暂停批量探台，约 8 秒后重试（正在播放的频道不受影响）')
                            self.ticket_tokens -= 1
                    ticket = source_ckey(profile['channelId'])
                    params = dict(YSP_PARAMS, livepid=profile['livePid'], cnlid=profile['channelId'],
                                  defn=profile.get('defn', 'fhd'), cKey=ticket['cKey'], guid=ticket['guid'],
                                  fntick=str(ticket['timestamp']), flowid=ticket['flowId'])
                    _, _, body, _ = self.fetch('https://bkliveinfo.ysp.cctv.cn/?' + urlparse.urlencode(params), {'User-Agent': 'qqlive'})
                    payload = json.loads(body)
                    if not isinstance(payload, dict):
                        raise LiveError('央视频接口返回格式错误')
                    if str(payload.get('iretcode')) != '0':
                        code = payload.get('iretcode', 'unknown')
                        raise LiveError('央视频拒绝请求（iretcode=' + str(code) + '）：' + str(payload.get('errinfo', ''))[:120])
                    if payload.get('livepid') is not None and str(payload['livepid']) != profile['livePid']:
                        raise LiveError('央视频返回频道与请求不一致')
                    if str(payload.get('encrypt', '0')) not in ('0', ''):
                        raise LiveError('此央视频流要求额外加密处理，当前新增源仅支持接口返回的公开流')
                    urls = [payload.get('playurl')]
                    backups = payload.get('backurl_list', payload.get('backurlList', payload.get('backurl', [])))
                    if isinstance(backups, str):
                        backups = re.split('[;,]', backups)
                    if isinstance(backups, list):
                        urls.extend(r if isinstance(r, str) else r.get('url', r.get('playurl')) for r in backups if isinstance(r, (dict, str)))
                    urls = list(dict.fromkeys(u for u in urls if isinstance(u, str) and valid_media_url(u)
                                             and urlparse.urlsplit(u).scheme == 'https'
                                             and (urlparse.urlsplit(u).hostname or '').endswith(('.cctv.cn', '.cctv.com'))))
                else:
                    urls = [profile['url']]
                if not urls:
                    raise LiveError('接口没有返回受支持的官方媒体地址')
                data = {'channel': channel, 'urls': urls}
                self.resolved[channel] = (time.monotonic(), data)
                with self.state_lock:
                    self.states.setdefault(channel, {}).update(api_ok=True, api_at=int(time.time()), last_error=None)
                return data
            except (LiveError, ValueError, TypeError, KeyError) as exc:
                message = str(exc) if isinstance(exc, LiveError) else '新增源接口响应格式错误'
                with self.state_lock:
                    self.states.setdefault(channel, {}).update(api_ok=False, last_error=message)
                raise LiveError(message) from None

    def stream_candidates(self, channel, data, include_kind=False):
        for url in data['urls']:
            yield (url, 'raw') if include_kind else url

    def rewrite(self, text, base, channel, origin, kind=None):
        if self.api_mode == 'ysp' and getattr(self.args, 'ysp_media', 'relay') == 'relay':
            return super().rewrite(text, base, channel, origin, kind)
        plain = '#EXT-X-STREAM-INF:' not in text and re.search(r'^#EXT-X-MEDIA-SEQUENCE:\s*\d+', text, re.M)
        unsupported = re.search(r'^#EXT-X-(?:KEY|MAP|BYTERANGE|DISCONTINUITY|PART)\b', text, re.M)
        if self.api_mode == 'ysp' and plain and not unsupported:
            lines = []
            with self.state_lock:
                pins = self.segment_pins.setdefault(channel, collections.OrderedDict())
                for line in text.splitlines():
                    if line.strip() and not line.startswith('#'):
                        target = urlparse.urljoin(base, line.strip())
                        filename = urlparse.urlsplit(target).path.rsplit('/', 1)[-1]
                        if re.fullmatch(r'[A-Za-z0-9_]+-\d+\.ts', filename):
                            if not valid_media_url(target):
                                raise LiveError('HLS 包含未支持的媒体地址')
                            previous = pins.get(filename)
                            public = previous[0] if previous else target
                            pins[filename] = (public, target)
                            pins.move_to_end(filename)
                            line = public
                    lines.append(line)
                while len(pins) > 64:
                    pins.popitem(last=False)
            text = '\n'.join(lines) + '\n'
        return super().rewrite(text, base, channel, origin, kind)

    def fetch_media(self, channel, target, headers):
        actual = target
        if self.api_mode == 'ysp':
            filename = urlparse.urlsplit(target).path.rsplit('/', 1)[-1]
            with self.state_lock:
                pin = self.segment_pins.get(channel, {}).get(filename)
            if pin and pin[0] == target:
                # Preserve the outward URL for AVPlayer while using the latest
                # official URL observed for that exact same segment filename.
                actual = pin[1]
        return self.fetch(actual, headers)

    def playlist(self, channel):
        if channel not in self.playlist_locks:
            raise LiveError('未知新增源频道')
        if self.api_mode != 'ysp':
            with self.playlist_locks[channel]:
                cached = self.manifest_cache.get(channel)
                if cached and time.monotonic() - cached[0] < 2:
                    return cached[1]
                result = self._playlist_fetch(channel)
                self.manifest_cache[channel] = time.monotonic(), result
                return result
        with self.state_lock:
            now = time.monotonic()
            cached = self.manifest_cache.get(channel)
            if cached and now - cached[0] < 2:
                return cached[1]
            cool = self.source_cooling.get(channel)
            if cool and now < cool[0]:
                if cached and now - cached[0] <= 30:
                    return cached[1]
                raise LiveError(cool[1])
            job = self.refresh_jobs.get(channel)
            if job is None:
                job = threading.Event()
                self.refresh_jobs[channel] = job
                threading.Thread(target=self._refresh_manifest, args=(channel, job), daemon=True).start()
            # Once a refresh has missed the deadline, return observed recent content
            # immediately on subsequent polls while that same job continues.
            immediate = channel in self.refresh_errors and cached and now - cached[0] <= 30
        if not immediate:
            job.wait(3.5 if cached and now - cached[0] <= 30 else self.args.timeout * 4 + 2)
        with self.state_lock:
            cached = self.manifest_cache.get(channel)
            if cached and time.monotonic() - cached[0] <= 30:
                if not job.is_set():
                    self.refresh_errors[channel] = '清单刷新尚未完成；暂回最近有效清单'
                return cached[1]
            raise LiveError(self.refresh_errors.get(channel, '央视频清单刷新超时；后台请求仍在进行'))

    def _refresh_manifest(self, channel, job):
        try:
            result = self._playlist_fetch(channel)
            with self.state_lock:
                self.manifest_cache[channel] = time.monotonic(), result
                self.refresh_errors.pop(channel, None)
                self.source_cooling.pop(channel, None)
        except Exception as exc:
            message = str(exc) if isinstance(exc, LiveError) else '央视频清单刷新异常'
            with self.state_lock:
                self.refresh_errors[channel] = message
                delay = 180 if '版权' in message else 30 if '403' in message else 5
                self.source_cooling[channel] = time.monotonic() + delay, message
                self.states.setdefault(channel, {}).update(playlist_ok=False, last_error=message)
        finally:
            with self.state_lock:
                self.refresh_jobs.pop(channel, None)
                job.set()

    def _playlist_fetch(self, channel):
        errors = []
        for force in (False, True):
            data = self.resolve(channel, force)
            for url in data['urls']:
                try:
                    status, _, body, final = self.fetch(url, self.media_headers(channel))
                    if status != 200 or not is_hls(body):
                        raise LiveError('官方源没有返回 HLS 清单')
                    text = body.decode('utf-8-sig')
                    # Validate every reference before exposing the playlist.
                    Client.rewrite(self, text, final, channel, 'http://localhost', 'raw')
                    with self.state_lock:
                        self.media_types[channel] = 'raw'
                        self.states.setdefault(channel, {}).update(playlist_ok=True, playlist_at=int(time.time()), media_type='raw')
                    return text, final
                except (LiveError, UnicodeError) as exc:
                    errors.append(str(exc) if isinstance(exc, LiveError) else '清单字符编码错误')
            # Fixed public addresses cannot be renewed; retrying them adds no value.
            if self.api_mode == 'regional' or (errors and all('403' in e for e in errors)):
                break
        message = errors[-1] if errors else '新增源当前不可用'
        with self.state_lock:
            self.states.setdefault(channel, {}).update(playlist_ok=False, last_error=message)
        raise LiveError(message)

    def channel_list(self):
        rows = super().channel_list()
        for row in rows:
            row['request_configured'] = True
            row['provider'] = self.profiles[row['id']]['provider']
            row['catchup'] = 'none'
        return rows

    def health(self):
        with self.state_lock:
            states = {k: dict(v) for k, v in self.states.items()}
        return {'service_ready': True, 'version': VERSION, 'source': self.api_mode,
                'api_mode': self.api_mode, 'channels': list(self.profiles),
                'subscription_channels': list(self.profiles), 'upstream': states,
                'video_processing': 'PUBLIC_HLS_PASSTHROUGH', 'media_delivery': getattr(self.args, 'ysp_media', 'relay') if self.api_mode == 'ysp' else 'proxy',
                'refresh_pending': len(self.refresh_jobs), 'epg': self.epg.stats(),
                'notice': 'HTTP 成功不代表视频已验证；4K/8K 取决于上游与播放设备解码能力。'}


class AptvCatalog:
    """Explicit same-channel mappings; retain the original catalogue and IDs."""
    def __init__(self, clients):
        self.clients = clients
        self.entries = {}
        self.lock = threading.Lock()
        self.active = {}
        self.failures = {}
        normal = lambda name: re.sub(r'[\s\-()（）]', '', name).casefold()
        original = clients.get('web') or (clients.get('app') if not clients.get('ysp') else None)
        if original:
            for ch, meta in original.metadata.items():
                if ch in original.subscription_channels:
                    self.entries[ch] = {'meta': dict(meta), 'sources': []}
        by_name = {normal(row['meta']['name']): ch for ch, row in self.entries.items()}
        aliases = {'ysp-cctv4': 'cctv4', 'ysp-cctv9': 'cctvjilu',
                   'ysp-cctv14': 'cctvchild', 'ysp-cctv5p': 'cctv5plus'}
        # Public sources have priority. Original App UDRM remains separate when
        # a working protocol is enabled; it is never presented as an automatic decoder.
        modes = [m for m in ('ysp', 'regional', 'web') if m in clients]
        if not modes and 'app' in clients:
            modes = ['app']
        for mode in modes:
            current = clients[mode]
            for ch, meta in current.metadata.items():
                if ch not in current.subscription_channels:
                    continue
                logical = aliases.get(ch)
                if logical not in self.entries:
                    logical = by_name.get(normal(meta['name']), ch)
                if mode == 'web':
                    logical = ch
                if logical not in self.entries:
                    self.entries[logical] = {'meta': dict(meta), 'sources': []}
                self.entries[logical]['sources'].append((mode, ch))
                by_name.setdefault(normal(meta['name']), logical)
        self.channel_locks = {ch: threading.Lock() for ch in self.entries}

    def playlist(self, channel):
        if channel not in self.entries:
            raise LiveError('未知 APTV 频道')
        with self.channel_locks[channel]:
            now = time.monotonic()
            candidates = list(self.entries[channel]['sources'])
            with self.lock:
                active = self.active.get(channel)
                if active and now - active['used_at'] < 90 and active['source'] in candidates:
                    candidates.remove(active['source'])
                    candidates.insert(0, active['source'])
                cooldown = dict(self.failures)
            usable, cooling = [], []
            for source in candidates:
                mode, ch = source
                current = self.clients[mode]
                with current.state_lock:
                    state = dict(current.states.get(ch, {}))
                recent_media_error = state.get('last_media_error') and time.time() - state.get('last_media_error_at', 0) < 30
                no_decoder = mode == 'web' and current.video_core is None and not shutil.which('node') and not current.args.audio
                if no_decoder or cooldown.get(source, {}).get('until', 0) > now or recent_media_error:
                    cooling.append(source)
                else:
                    usable.append(source)
            # If every source is cooling down, return the known failure briefly
            # instead of retrying every dead CDN on every APTV playlist poll.
            if not usable:
                reasons = []
                for mode, ch in cooling:
                    with self.clients[mode].state_lock:
                        last = dict(self.clients[mode].states.get(ch, {}))
                    reason = last.get('last_media_error') or cooldown.get((mode, ch), {}).get('error')
                    if reason:
                        reasons.append(mode + ': ' + reason)
                raise LiveError('频道 ' + channel + ' 同台来源暂不可用；' + ('；'.join(reasons) if reasons else '请查看 /aptv/channels.json'))
            errors = []
            for mode, ch in usable:
                current = self.clients[mode]
                try:
                    text, base = current.playlist(ch)
                    if current.media_types.get(ch) == 'cdrm' and current.video_core is None:
                        raise LiveError('此备用源需要 Node.js CDRM 内核')
                    with self.lock:
                        self.active[channel] = {'source': (mode, ch), 'used_at': time.monotonic()}
                        self.failures.pop((mode, ch), None)
                    return current, ch, text, base
                except LiveError as exc:
                    errors.append(mode + ': ' + str(exc))
                    with self.lock:
                        self.failures[(mode, ch)] = {'until': time.monotonic() + 20, 'error': str(exc)}
            raise LiveError('同台来源均失败：' + '；'.join(errors))

    def m3u(self, origin):
        clean = lambda value: str(value).replace('\r', '').replace('\n', '').replace('"', "'")
        lines = [f'#EXTM3U x-tvg-url="{origin}/aptv-epg.xml.gz" url-tvg="{origin}/aptv-epg.xml.gz"',
                 '#EXT-X-APTV-PREVIEW: FALSE', '#EXT-X-APTV-LATENCY: FALSE']
        for ch, row in self.entries.items():
            meta = row['meta']
            lines.extend([f'#EXTINF:-1 tvg-id="{ch}" tvg-name="{clean(meta["name"])}" tvg-logo="{clean(meta["logo"])}" group-title="{clean(meta["group"])}" catchup="none",{clean(meta["name"])}',
                          f'{origin}/aptv/play/{ch}.m3u8'])
        return '\n'.join(lines) + '\n'

    def xml(self, wait):
        stores = list(dict.fromkeys(c.epg for c in self.clients.values()))
        for store in stores:
            store.trigger()
        deadline = time.monotonic() + wait
        for store in stores:
            with store.lock:
                ready = bool(store.rows)
            if not ready:
                store.done.wait(max(0, deadline - time.monotonic()))
        snapshots = {}
        for mode, current in self.clients.items():
            with current.epg.lock:
                snapshots[mode] = dict(current.epg.rows)
        root = ET.Element('tv', {'generator-info-name': 'cbox-live ' + VERSION})
        tz = datetime.timezone(datetime.timedelta(hours=8))
        stamp = lambda t: datetime.datetime.fromtimestamp(t, tz).strftime('%Y%m%d%H%M%S %z')
        now = time.time()
        for ch, row in self.entries.items():
            element = ET.SubElement(root, 'channel', {'id': ch})
            ET.SubElement(element, 'display-name', {'lang': 'zh'}).text = row['meta']['name']
            if row['meta'].get('logo'):
                ET.SubElement(element, 'icon', {'src': row['meta']['logo']})
            alternatives = [snapshots[mode].get(source, []) for mode, source in row['sources']]
            # Select a complete schedule from one provider; no overlapping
            # schedules from different sources are merged into the same ID.
            programmes = next((rows for rows in alternatives if any(r['end'] > now for r in rows)),
                              next((rows for rows in alternatives if rows), []))
            for item in programmes:
                program = ET.SubElement(root, 'programme', {'channel': ch,
                    'start': stamp(item['start']), 'stop': stamp(item['end'])})
                ET.SubElement(program, 'title', {'lang': 'zh'}).text = item['title']
        return ET.tostring(root, encoding='utf-8', xml_declaration=True)

    def status(self):
        with self.lock:
            active, failures = dict(self.active), dict(self.failures)
        rows = []
        for ch, row in self.entries.items():
            sources = []
            for mode, source in row['sources']:
                current = self.clients[mode]
                with current.state_lock:
                    state = dict(current.states.get(source, {}))
                failure = failures.get((mode, source), {})
                media_wait = max(0, 30 - (time.time() - state.get('last_media_error_at', 0))) if state.get('last_media_error') else 0
                runtime_supported = not (mode == 'web' and current.video_core is None and not current.args.audio) and mode != 'app'
                sources.append({'mode': mode, 'channel': source, 'state': state,
                                'runtime_supported': runtime_supported,
                                'cooldown_seconds': max(0, round(failure.get('until', 0) - time.monotonic()), round(media_wait)),
                                'error': failure.get('error') or state.get('last_media_error')})
            selected = active.get(ch, {}).get('source')
            rows.append({'id': ch, **row['meta'], 'sources': sources,
                         'active_source': {'mode': selected[0], 'channel': selected[1]} if selected else None})
        return {'channels': len(rows), 'original_catalogue_preserved': all(ch in self.entries for ch in CATALOG)
                if 'web' in self.clients else None, 'rows': rows}


def handler_for(client, app_client=None, source_clients=None):
    default_client = client
    clients = {client.api_mode: client}
    if app_client is not None:
        clients[app_client.api_mode] = app_client
    clients.update({c.api_mode: c for c in (source_clients or [])})
    aptv = AptvCatalog(clients)
    capability_notice_at = {'time': float('-inf')}
    warning_times = {}
    mobile_default = (default_client.api_mode == 'web' and default_client.video_core is None
                      and not shutil.which('node') and 'ysp' in clients and not default_client.args.audio)
    class Handler(BaseHTTPRequestHandler):
        protocol_version = 'HTTP/1.1'

        def setup(self):
            super().setup()
            self.connection.settimeout(30)

        def handle(self):
            try:
                super().handle()
            except (ConnectionResetError, BrokenPipeError, TimeoutError):
                # iOS APTV cancels probes and keep-alive sockets while changing
                # channels. Handle resets at the read loop, outside do_GET too.
                self.close_connection = True

        def finish(self):
            try:
                super().finish()
            except (ConnectionResetError, BrokenPipeError):
                self.close_connection = True

        def log_message(self, *_):
            pass

        def send(self, code, body, mime='text/plain; charset=utf-8', extra=None):
            body = body.encode('utf-8') if isinstance(body, str) else body
            epg = urlparse.urlsplit(self.path).path.endswith(('epg.xml', 'epg.xml.gz'))
            etag = '"' + hashlib.sha256(body).hexdigest() + '"' if epg and code == 200 else None
            if etag and self.headers.get('If-None-Match') == etag:
                self.send_response(304)
                self.send_header('ETag', etag)
                self.send_header('Cache-Control', 'max-age=60, must-revalidate')
                self.send_header('Access-Control-Allow-Origin', '*')
                self.end_headers()
                return
            self.send_response(code)
            if etag:
                self.send_header('ETag', etag)
            self.send_header('Content-Type', mime)
            self.send_header('Content-Length', str(len(body)))
            self.send_header('Cache-Control', 'max-age=60, must-revalidate' if epg else 'no-store')
            self.send_header('Access-Control-Allow-Origin', '*')
            for k, v in (extra or {}).items():
                self.send_header(k, v)
            self.end_headers()
            if self.command != 'HEAD':
                self.wfile.write(body)

        def origin(self):
            selected = getattr(self, 'selected_client', default_client)
            prefix = getattr(self, 'route_prefix', '')
            if selected.args.public_base:
                return selected.args.public_base.rstrip('/') + prefix
            host = self.headers.get('Host', '')
            if not host or not re.fullmatch(r'[A-Za-z0-9.\-\[\]:]+', host):
                raise LiveError('Host 请求头不正确')
            return 'http://' + host + prefix

        def do_HEAD(self):
            # Known channel HEAD probes confirm route presence, not playback;
            # do not acquire tickets or consume a media request for a scan.
            path = urlparse.urlsplit(self.path).path
            selected = default_client
            prefixed = False
            for mode, current in clients.items():
                if path.startswith('/' + mode + '/'):
                    selected = current
                    path = path[len(mode) + 1:]
                    prefixed = True
                    break
            known = False
            if path.startswith('/aptv/play/') and path.endswith('.m3u8'):
                known = path[len('/aptv/play/'):-5] in aptv.entries
            elif re.fullmatch(r'/[A-Za-z0-9_-]+\.m3u8', path):
                channel = path[1:-5]
                known = channel in selected.profiles or (mobile_default and not prefixed and channel in aptv.entries)
            if known:
                self.send(200, b'', 'application/vnd.apple.mpegurl')
                return
            self.do_GET()

        def do_GET(self):
            try:
                path = urlparse.urlsplit(self.path).path
                self.route_prefix = ''
                self.request_channel = None
                self.request_mode = 'route'
                mode = default_client.api_mode
                for candidate in ('web', 'app', 'ysp', 'regional'):
                    if path == '/' + candidate or path.startswith('/' + candidate + '/'):
                        self.route_prefix = '/' + candidate
                        mode = candidate
                        path = path[len(self.route_prefix):] or '/'
                        break
                client = default_client if not self.route_prefix else clients.get(mode)
                if client is None:
                    self.send(503, '当前未启用此模式；可用 --api-mode both 同时启动两种模式')
                    return
                self.selected_client = client
                if path == '/modes.json':
                    self.send(200, json.dumps({'default_mode': default_client.api_mode, 'mobile_default': bool(mobile_default), 'recommended_subscription': '/aptv.m3u', 'modes': {k: v.health() for k, v in clients.items()}}, ensure_ascii=False, indent=2), 'application/json; charset=utf-8')
                elif path == '/aptv.m3u' or (mobile_default and not self.route_prefix and path in ('/all.m3u', '/playlist.m3u')):
                    origin = self.origin()
                    if self.route_prefix:
                        origin = origin[:-len(self.route_prefix)]
                    self.send(200, aptv.m3u(origin), 'audio/x-mpegurl; charset=utf-8')
                elif path in ('/aptv-epg.xml', '/aptv-epg.xml.gz') or (mobile_default and not self.route_prefix and path in ('/epg.xml', '/epg.xml.gz')):
                    body = aptv.xml(client.args.epg_wait)
                    if path.endswith('.gz'):
                        body = gzip.compress(body, mtime=0)
                    self.send(200, body, 'application/gzip' if path.endswith('.gz') else 'application/xml; charset=utf-8')
                elif path == '/aptv/channels.json':
                    self.send(200, json.dumps(aptv.status(), ensure_ascii=False, indent=2), 'application/json; charset=utf-8')
                elif path == '/diagnostics.json':
                    import os
                    snapshot = {'version': VERSION, 'python': sys.version.split()[0],
                                'node_available': bool(shutil.which('node')),
                                'proxy_environment_set': any(bool(os.environ.get(k)) for k in ('HTTPS_PROXY', 'HTTP_PROXY', 'https_proxy', 'http_proxy')),
                                'channels': aptv.status(), 'modes': {k: v.health() for k, v in clients.items()}}
                    self.send(200, json.dumps(snapshot, ensure_ascii=False, indent=2), 'application/json; charset=utf-8')
                elif path == '/config-catalog.json':
                    self.send(200, gzip.decompress(base64.b85decode(CONFIG_CATALOG_B85)), 'application/json; charset=utf-8')
                elif re.fullmatch(r'/aptv/play/[A-Za-z0-9_-]+\.m3u8', path):
                    logical = path[len('/aptv/play/'):-5]
                    self.request_channel, self.request_mode = logical, 'aptv'
                    if logical not in aptv.entries:
                        self.send(404, '未知 APTV 频道')
                        return
                    current, source, text, base = aptv.playlist(logical)
                    origin = self.origin()
                    if self.route_prefix:
                        origin = origin[:-len(self.route_prefix)]
                    origin += '/' + current.api_mode
                    self.send(200, current.rewrite(text, base, source, origin), 'application/vnd.apple.mpegurl; charset=utf-8',
                              {'X-Playback-Source': current.api_mode, 'X-Playback-Channel': source})
                elif path in ('/combined.m3u', '/combined-epg.xml', '/combined-epg.xml.gz'):
                    origin = self.origin()
                    if self.route_prefix:
                        origin = origin[:-len(self.route_prefix)]
                    visible = [(k, c) for k, c in clients.items() if k != 'app' or len(clients) == 1]
                    if not any(k in ('web', 'ysp', 'regional') for k, c in visible):
                        visible = list(clients.items())
                    if path == '/combined.m3u':
                        lines = [f'#EXTM3U x-tvg-url="{origin}/combined-epg.xml.gz" url-tvg="{origin}/combined-epg.xml.gz"',
                                 '#EXT-X-APTV-PREVIEW: FALSE', '#EXT-X-APTV-LATENCY: FALSE']
                        clean = lambda value: str(value).replace('\r', '').replace('\n', '').replace('"', "'")
                        for mode, current in visible:
                            label = {'web': 'CDRM', 'app': 'App UDRM', 'ysp': '央视频', 'regional': '广电官方源'}[mode]
                            for ch, meta in current.metadata.items():
                                if ch not in current.subscription_channels:
                                    continue
                                lines.extend([f'#EXTINF:-1 tvg-id="{ch}" tvg-name="{clean(meta["name"])}" tvg-logo="{clean(meta["logo"])}" group-title="{label} · {clean(meta["group"])}" catchup="none",{clean(meta["name"])}',
                                              f'{origin}/{mode}/{ch}.m3u8'])
                        self.send(200, '\n'.join(lines) + '\n', 'audio/x-mpegurl; charset=utf-8')
                    else:
                        root = ET.Element('tv', {'generator-info-name': 'cbox-live ' + VERSION})
                        # Start all providers together, then respect the first-load wait budget once.
                        for _, current in visible:
                            current.epg.trigger()
                        deadline = time.monotonic() + client.args.epg_wait
                        for _, current in visible:
                            with current.epg.lock:
                                ready = bool(current.epg.rows)
                            if not ready:
                                current.epg.done.wait(max(0, deadline - time.monotonic()))
                            root.extend(ET.fromstring(current.epg.snapshot_xml()))
                        body = ET.tostring(root, encoding='utf-8', xml_declaration=True)
                        if path.endswith('.gz'):
                            body = gzip.compress(body, mtime=0)
                        self.send(200, body, 'application/gzip' if path.endswith('.gz') else 'application/xml; charset=utf-8')
                elif path in ('/health', '/diag'):
                    self.send(200, json.dumps(client.health(), ensure_ascii=False, indent=2), 'application/json; charset=utf-8')
                elif path == '/channels.json':
                    self.send(200, json.dumps(client.channel_list(), ensure_ascii=False, indent=2), 'application/json; charset=utf-8')
                elif path in ('/epg.xml', '/epg.xml.gz'):
                    body = client.epg.xml()
                    if path.endswith('.gz'):
                        body = gzip.compress(body, mtime=0)
                    stats = client.epg.stats()
                    self.send(200, body, 'application/gzip' if path.endswith('.gz') else 'application/xml; charset=utf-8',
                              {'X-EPG-Channels': str(stats['channels_with_programmes']),
                               'X-EPG-State': 'refreshing' if stats['refreshing'] else 'cached'})
                elif path == '/':
                    origin = self.origin()
                    self.send(200, f'央视影音 VDN 代理 {VERSION}\n{NOTICE}\n当前模式：{client.api_mode}；保留目录 {len(client.profiles)} 台\n\nAPTV 推荐订阅：{origin}/aptv.m3u\n推荐节目单：{origin}/aptv-epg.xml.gz\n诊断：{origin}/diag\n所有来源状态：{origin}/modes.json\n合并订阅（新增央视频及广电）：{origin}/combined.m3u\n')
                elif path in ('/all.m3u', '/playlist.m3u'):
                    origin = self.origin()
                    lines = [f'#EXTM3U x-tvg-url="{origin}/epg.xml.gz" url-tvg="{origin}/epg.xml.gz"', '#EXT-X-APTV-PREVIEW: FALSE', '#EXT-X-APTV-LATENCY: FALSE']
                    group_filter = urlparse.parse_qs(urlparse.urlsplit(self.path).query).get('group', [''])[0]
                    clean = lambda value: str(value).replace('\r', '').replace('\n', '').replace('"', "'")
                    for channel in client.profiles:
                        if channel not in client.subscription_channels:
                            continue
                        meta = client.metadata[channel]
                        if group_filter and group_filter != meta['group']:
                            continue
                        name = clean(meta['name']) + (' 音频' if client.args.audio else '')
                        mode_label = {'web': 'CDRM', 'app': 'App UDRM', 'ysp': '央视频', 'regional': '广电官方源'}[client.api_mode]
                        lines += [f'#EXTINF:-1 tvg-id="{channel}" tvg-name="{name}" tvg-logo="{clean(meta["logo"])}" group-title="{mode_label} · {clean(meta["group"])}" catchup="none",{name}',
                                  f'{origin}/{channel}.m3u8']
                    self.send(200, '\n'.join(lines) + '\n', 'audio/x-mpegurl; charset=utf-8')
                elif path.startswith('/proxy/'):
                    try:
                        channel, target, media_kind = client.untoken(path[len('/proxy/'):])
                    except LiveError as exc:
                        self.send(403, str(exc))
                        return
                    self.request_channel = channel
                    self.request_mode = client.api_mode
                    range_value = self.headers.get('Range')
                    if range_value and not re.fullmatch(r'bytes=(?:\d+-\d*|-\d+)', range_value):
                        self.send(416, '仅支持单一字节范围')
                        return
                    processed = client.should_process(target, media_kind) and '.ts' in urlparse.urlsplit(target).path
                    if processed and client.video_core is None:
                        raise MediaCapabilityError('此旧媒体地址需要网页 CDRM 内核；请刷新 /aptv.m3u 或默认订阅')
                    status, rh, body, final = client.load_asset(channel, target, media_kind, range_value, processed)
                    if is_hls(body):
                        rewritten = client.rewrite(body.decode('utf-8-sig'), final, channel, self.origin(), media_kind)
                        self.send(status, rewritten, 'application/vnd.apple.mpegurl; charset=utf-8')
                    else:
                        if processed or (client.api_mode == 'ysp' and urlparse.urlsplit(target).path.lower().endswith('.ts')):
                            status, body, extra = local_range(body, range_value)
                        else:
                            extra = {k: rh[k] for k in ('content-range', 'accept-ranges') if k in rh}
                        with client.state_lock:
                            client.states.setdefault(channel, {}).update(last_media_error=None, last_media_at=int(time.time()))
                        self.send(status, body, rh.get('content-type', 'application/octet-stream'), extra)
                elif re.fullmatch(r'/[A-Za-z0-9_-]+\.m3u8', path):
                    channel = path[1:-5]
                    self.request_channel, self.request_mode = channel, ('aptv' if mobile_default and not self.route_prefix else client.api_mode)
                    if channel not in client.profiles:
                        self.send(404, '没有此频道的抓包配置')
                        return
                    if mobile_default and not self.route_prefix and channel in aptv.entries:
                        current, source, text, base = aptv.playlist(channel)
                        self.send(200, current.rewrite(text, base, source, self.origin() + '/' + current.api_mode),
                                  'application/vnd.apple.mpegurl; charset=utf-8',
                                  {'X-Playback-Source': current.api_mode, 'X-Playback-Channel': source})
                    else:
                        text, base = client.playlist(channel)
                        self.send(200, client.rewrite(text, base, channel, self.origin()), 'application/vnd.apple.mpegurl; charset=utf-8')
                else:
                    self.send(404, 'not found')
            except (BrokenPipeError, ConnectionResetError):
                pass
            except Exception as exc:
                message = str(exc) if isinstance(exc, LiveError) else '响应处理失败'
                if isinstance(exc, MediaCapabilityError):
                    with aptv.lock:
                        emit_notice = time.monotonic() - capability_notice_at['time'] >= 60
                        if emit_notice:
                            capability_notice_at['time'] = time.monotonic()
                    if emit_notice:
                        LOG.info('检测到需要 Node 的旧网页媒体入口；请刷新默认订阅或使用 /aptv.m3u（相同提示一分钟最多一次）')
                else:
                    tag = getattr(self, 'request_mode', 'route') + '/' + str(getattr(self, 'request_channel', None) or '-')
                    warning_key = (tag, message)
                    with aptv.lock:
                        emit_warning = time.monotonic() - warning_times.get(warning_key, float('-inf')) >= 10
                        if emit_warning:
                            warning_times[warning_key] = time.monotonic()
                        if len(warning_times) > 256:
                            for key in list(warning_times)[:128]:
                                warning_times.pop(key, None)
                    if emit_warning:
                        LOG.warning('[%s] %s', tag, message)
                try:
                    self.send(503 if isinstance(exc, MediaCapabilityError) else 502, message + '\n查看 /aptv/channels.json 或 /diag 获取状态。\n')
                except (BrokenPipeError, ConnectionResetError):
                    pass
    return Handler


def inspect_sample(path):
    ffmpeg = shutil.which('ffmpeg')
    if not ffmpeg:
        return {'decode_test': 'not_run', 'reason': '未安装 ffmpeg；无法验证画面解码'}
    try:
        result = subprocess.run([ffmpeg, '-nostdin', '-v', 'error', '-i', str(path),
                                 '-map', '0:v:0', '-t', '4', '-f', 'null', '-'],
                                capture_output=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        return {'decode_test': 'failed', 'reason': 'ffmpeg 执行失败或超时'}
    errors = result.stderr.decode('utf-8', errors='replace').strip().splitlines()
    # ffmpeg 可在损坏帧情况下返回 0，必须同时检查错误日志。
    return {'decode_test': 'passed' if result.returncode == 0 and not errors else 'failed',
            'ffmpeg_exit': result.returncode, 'error_lines': len(errors),
            'diagnostics': errors[:8], 'scope': '仅测试所提供样本，不保证后续直播或 APTV 兼容性'}


def doctor(client, channel):
    text, base = client.playlist(channel)
    # 沿主/子清单追踪，最多 4 层；优先最高的已返回变体。
    for _ in range(4):
        media = [x.strip() for x in text.splitlines() if x.strip() and not x.startswith('#')]
        if not media:
            raise LiveError('清单没有可请求的媒体条目')
        master = '#EXT-X-STREAM-INF:' in text
        target = urlparse.urljoin(base, media[0] if master else media[-1])
        status, headers, body, final = client.fetch(target, client.media_headers(channel))
        if is_hls(body):
            text, base = body.decode('utf-8-sig'), final
            continue
        with tempfile.TemporaryDirectory(prefix='cbox-doctor-') as td:
            path = Path(td) / 'sample.ts'
            body = client.process_segment(channel, final, body)
            path.write_bytes(body)
            result = inspect_sample(path)
            with client.state_lock:
                client.states.setdefault(channel, {}).update(video_decode=result['decode_test'], decode_checked_at=int(time.time()))
            return {'channel': channel, 'sample_http': status, 'sample_bytes': len(body),
                    'api_mode': client.api_mode, 'notice': NOTICE, **result}
    raise LiveError('清单嵌套超过诊断深度')


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('port', nargs='?', type=int, default=8767)
    parser.add_argument('--bind', default='0.0.0.0')
    parser.add_argument('--public-base', help='反向代理外部地址，例如 https://tv.example.com')
    parser.add_argument('--har', action='append', default=[], help='导入原 App 签名请求（--api-mode app 使用），可重复')
    parser.add_argument('--api-mode', choices=['both', 'web', 'app', 'ysp', 'regional'], default='both', help='默认保留双模式；央视频签名为纯 Python；仅网页 CDRM 需要 Node.js 18+')
    parser.add_argument('--extra-sources', choices=['all', 'none', 'ysp', 'regional'], default='all', help='新增来源，默认同时提供央视频及宁夏/黑龙江官方源；合并订阅 /combined.m3u')
    parser.add_argument('--licenses', action='store_true', help='显示新增源上游署名和 GPL-3.0 许可证')
    parser.add_argument('--verify-streams', action='store_true', help='配合 --probe-all/--available-only，额外逐台抽检分片解码（需 FFmpeg）')
    parser.add_argument('--check-start', action='store_true', help='启动时检测频道状态，但保留全部目录，不删台')
    parser.add_argument('--available-only', action='store_true', help=argparse.SUPPRESS)
    parser.add_argument('--probe-all', action='store_true', help='并发检查目录中所有频道的 API 可用性，不代表逐台解码测试')
    parser.add_argument('--data-dir', default=str(Path.home() / '.cache' / 'cbox-live'), help='EPG 磁盘缓存目录；传空字符串禁用')
    parser.add_argument('--epg-ttl', type=float, default=3600, help='节目单刷新间隔秒数，默认 3600')
    parser.add_argument('--epg-wait', type=float, default=20, help='首次请求节目单的最长等待秒数，默认 20')
    parser.add_argument('--channels', help='限制所选主模式频道；原模式如 cctv1,cctv2；央视频如 ysp-cctv1,ysp-hnws')
    parser.add_argument('--timeout', type=float, default=8)
    parser.add_argument('--resolve-ttl', type=float, default=30)
    parser.add_argument('--ysp-media', choices=['relay', 'proxy'], default='relay', help='央视频默认仅代理清单、播放器直连分片；proxy 保留分片转发诊断模式')
    parser.add_argument('--ysp-ticket-ttl', type=float, default=300, help='央视频官方取票缓存秒数，默认 300；清单继续独立刷新')
    parser.add_argument('--cache-mb', type=int, default=64)
    parser.add_argument('--direct', action='store_true', help='忽略 HTTP(S)_PROXY 环境变量，直连上游')
    parser.add_argument('--backup', action='store_true', help='优先使用备用 CDN')
    parser.add_argument('--audio', action='store_true', help='转发接口返回的独立音频地址')
    parser.add_argument('--compare', metavar='CHANNEL', help='同一频道分别检查网页 CDRM 与原 App UDRM；默认双模式，需 Node.js，解码检查需 FFmpeg')
    parser.add_argument('--doctor', metavar='CHANNEL', help='检查接口/清单/分片并用 ffmpeg 检查视频解码')
    parser.add_argument('--sample', type=Path, help='离线检查已有 TS 样本，需 ffmpeg')
    args = parser.parse_args(argv)
    if args.licenses:
        print('Additional source integration adapted from akiralereal/iptv, commit e475b2f6d24029f844ada2b362d703c8b88c2e9b.\nhttps://github.com/akiralereal/iptv\nGPL-3.0; modifications: Python integration, signed proxy routing, aggregated M3U/XMLTV.\n')
        print(gzip.decompress(base64.b85decode(SOURCE_GPL_B85)).decode())
        return 0
    if not 1 <= args.port <= 65535 or args.timeout <= 0 or args.resolve_ttl < 0 or args.ysp_ticket_ttl < 0 or args.cache_mb < 0 or args.epg_ttl < 60 or not 0 <= args.epg_wait <= 60:
        parser.error('端口须为 1–65535，超时须大于 0；EPG TTL 至少 60 秒，首次 EPG 等待 0–60 秒，其他 TTL/缓存不得为负数')
    if args.audio and args.api_mode in ('ysp', 'regional'):
        parser.error('新增央视频及地方官方源暂不支持 --audio；请选择视频播放')
    if args.compare and (args.api_mode != 'both' or args.doctor or args.probe_all):
        parser.error('--compare 需使用 --api-mode both，且不能同时使用 --doctor 或 --probe-all')
    if args.verify_streams and not (args.probe_all or args.check_start or args.available_only):
        parser.error('--verify-streams 需要配合 --probe-all 或 --check-start')
    if args.verify_streams and not shutil.which('ffmpeg'):
        parser.error('--verify-streams 需要已安装的 ffmpeg')
    if args.public_base:
        u = urlparse.urlsplit(args.public_base)
        if u.scheme not in ('http', 'https') or not u.hostname or u.username or u.password or u.query or u.fragment or any(c in args.public_base for c in '\r\n'):
            parser.error('--public-base 必须是有效 HTTP(S) 地址，不能包含认证、查询参数或片段')
    logging.basicConfig(level=logging.INFO, stream=sys.stdout, format='%(asctime)s [%(levelname)s] %(message)s')
    LOG.info('cbox-live v%s；Python %s；运行线程 %s', VERSION, sys.version.split()[0], 'main' if threading.current_thread() is threading.main_thread() else 'hosted')
    client = None
    app_client = None
    source_clients = []
    server = None
    try:
        if args.sample:
            result = inspect_sample(args.sample)
            print(json.dumps(result, ensure_ascii=False, indent=2))
            return 0 if result['decode_test'] == 'passed' else 2
        client = SourceClient(args, args.api_mode) if args.api_mode in ('ysp', 'regional') else Client(args)
        if args.api_mode == 'both':
            app_args = argparse.Namespace(**vars(args))
            app_args.api_mode = 'app'
            app_client = Client(app_args, init_epg=False)
            app_client.epg = client.epg
        selected_sources = ('ysp', 'regional') if args.extra_sources == 'all' else (() if args.extra_sources == 'none' else (args.extra_sources,))
        for mode in selected_sources:
            if mode != client.api_mode:
                extra_args = argparse.Namespace(**vars(args))
                extra_args.channels = None
                source_clients.append(SourceClient(extra_args, mode))
        if args.compare:
            clients_to_test = [client, app_client]
            def compare_one(current):
                try:
                    return doctor(current, args.compare)
                except LiveError as exc:
                    return {'api_mode': current.api_mode, 'channel': args.compare, 'decode_test': 'not_run', 'error': str(exc)}
            with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
                results = list(pool.map(compare_one, clients_to_test))
            print(json.dumps({'catalog_preserved': True, 'results': results}, ensure_ascii=False, indent=2))
            return 0 if all(r.get('decode_test') == 'passed' for r in results) else 2
        if args.probe_all:
            try:
                audits = {client.api_mode: client.probe_all(args.verify_streams)}
                if app_client is not None:
                    audits['app'] = app_client.probe_all(args.verify_streams)
                for extra in source_clients:
                    audits[extra.api_mode] = extra.probe_all(args.verify_streams)
                report = {'catalog_preserved': True, 'modes': audits} if len(audits) > 1 else audits[client.api_mode]
                print(json.dumps(report, ensure_ascii=False, indent=2))
                return 0
            finally:
                client.close()
        if args.doctor:
            if args.doctor not in client.profiles:
                raise LiveError('没有指定频道的抓包配置')
            try:
                result = doctor(client, args.doctor)
            finally:
                client.close()
            print(json.dumps(result, ensure_ascii=False, indent=2))
            return 0 if result['decode_test'] == 'passed' else 2
        if args.check_start or args.available_only:
            LOG.info('检查 %s 个目录频道的接口可用性…', len(client.profiles))
            audit = client.probe_all(args.verify_streams)
            LOG.info('%s 目录保留 %s 台；API 允许 %s 台，解码抽检通过 %s 台；检测不删台', client.api_mode, len(client.profiles), audit['api_available'], audit['sample_decode_passed'])
            if app_client is not None:
                app_audit = app_client.probe_all(args.verify_streams)
                LOG.info('app 目录保留 %s 台；已有模板 %s 台，API 允许 %s 台，解码抽检通过 %s 台；检测不删台', len(app_client.profiles), sum(bool(v.get('url')) for v in app_client.profiles.values()), app_audit['api_available'], app_audit['sample_decode_passed'])
        if args.check_start or args.available_only:
            for extra in source_clients:
                audit = extra.probe_all(args.verify_streams)
                LOG.info('%s 保留 %s 路，样本解码通过 %s 路', extra.api_mode, len(extra.profiles), audit['sample_decode_passed'])
        server = ThreadingHTTPServer((args.bind, args.port), handler_for(client, app_client, source_clients))
        LOG.info('新增来源 %s；APTV 合并订阅 /combined.m3u', {c.api_mode: len(c.profiles) for c in [client, *source_clients]})
        server.daemon_threads = True
        if client.api_mode == 'web' and client.video_core is None and any(c.api_mode == 'ysp' for c in source_clients):
            LOG.info('无 Node 兼容入口：/all.m3u 自动使用 APTV 同台多源目录；手机内置服务可用 http://127.0.0.1:%s/aptv.m3u', args.port)
        if client.api_mode == 'app':
            LOG.warning(NOTICE)
        elif client.api_mode == 'web':
            if client.video_core:
                LOG.info('网页 CDRM 视频核心已就绪；APTV 推荐 /aptv.m3u')
            else:
                LOG.warning('未安装 Node.js：网页 CDRM 不可解码；纯 Python 央视频仍可使用 /aptv.m3u')
        else:
            LOG.info('新增 %s 官方来源已登记，取流和解码结果见 /diag', client.api_mode)
        LOG.info('监听 %s:%s；主模式目录 %s 台 / 保留目录 %s 台；手机 APTV 推荐 http://运行设备的局域网IP:%s/aptv.m3u',
                 args.bind, args.port, len(client.subscription_channels), len(client.profiles), args.port)
        def terminate_handler(signum, frame):
            raise KeyboardInterrupt
        previous_term = None
        signal_registered = False
        if threading.current_thread() is threading.main_thread():
            try:
                previous_term = signal.signal(signal.SIGTERM, terminate_handler)
                signal_registered = True
            except (ValueError, OSError, AttributeError) as exc:
                LOG.info('运行环境不支持退出信号注册（%s）；继续提供 HTTP 服务', type(exc).__name__)
        else:
            LOG.info('托管线程运行：跳过进程信号注册，继续提供 HTTP 服务')
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()
            if signal_registered:
                try:
                    signal.signal(signal.SIGTERM, previous_term)
                except (ValueError, OSError, AttributeError):
                    LOG.info('运行环境未恢复退出信号，HTTP 服务已关闭')
        return 0
    except (LiveError, OSError, ValueError) as exc:
        message = str(exc) if isinstance(exc, LiveError) else type(exc).__name__ + ': ' + str(exc)
        print('错误：' + message, file=sys.stderr)
        return 1
    finally:
        if server is not None:
            server.server_close()
        for additional in source_clients:
            additional.close()
        if app_client is not None:
            app_client.close()
        if client is not None:
            client.close()


if __name__ == '__main__':
    sys.exit(main())
